ruleBookInfo.init:
@js:if(baseUrl.slice(0,4)=="http"){
	book.canUpdate=false
	let aa =result.indexOf("title",950)+6
		let bb = result.indexOf("title",aa)-2-17
		let url = baseUrl.slice(30).split("/att")
		if(url.length!=1)bb=result.indexOf(" - "+baseUrl.match(/(\d+).$/)[1],aa)
		let obj={name:"",coverUrl:"",tocUrl:""}
	obj.name=result.slice(aa,bb)
	aa =result.indexOf("preload",950)+15
		bb = result.indexOf("\"",aa)
		obj.coverUrl=result.slice(aa,bb)
		book.bookUrl='data:;base64,'+java.base64Encode(url[0])+',{"type":""}'
		obj.tocUrl=book.bookUrl
		obj
	}else ""

ruleContent.content:
@js:if(book.type==64||book.type==1088){
    let results = [];
    let searchTerm = "<amp-img";
    let index = 0;

    while (index < result.length) {

        let imgPathIndex = result.indexOf(searchTerm, index);
        if (imgPathIndex === -1) break;


        let pathStart = imgPathIndex + searchTerm.length+25;

            let path = result.slice(pathStart, result.indexOf("\"",pathStart));
            results.push(path);

        index = pathStart + 200;

    }
    result=[]
    results.map(i=>result.push("<img src=\""+i+"\">"))
   result.join("")


	}else{

   let pathStart = result.indexOf("source") +12
   let path = result.slice(pathStart, result.indexOf("\"",pathStart));
   java.startBrowser(path,book.name)
   path
		}

